/*
 * A191287  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then floor(3x/2) and 3x are in a.
 * https://oeis.org/A191287
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 24, u16 n <= 2288, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 89 terms through n = 9595 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generates OEIS sequence A191287: a(1)=1, and for each x in the sequence
   the numbers floor(3x/2) and 3x are also in the sequence. */
/* The implementation keeps a sorted unique table of generated terms
   and expands it until it contains at least n elements. */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/mem.h"

/* insert val into sorted array *arr of length *len and capacity *cap.
   If val is already present, nothing is changed. */
static void seq_insert(seq_t **arr, size_t *len, size_t *cap, seq_t val)
{
    size_t lo = 0, hi = *len;
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        if ((*arr)[mid] < val)
            lo = mid + 1;
        else
            hi = mid;
    }
    if (lo < *len && (*arr)[lo] == val)
        return;                      /* already present */

    if (*len == *cap) {               /* grow array */
        *cap = (*cap == 0 ? 16 : (*cap << 1));
        *arr = mem_resize(seq_t, *arr, (*cap * sizeof(seq_t)) / sizeof(seq_t));
    }

    for (size_t i = *len; i > lo; --i)
        (*arr)[i] = (*arr)[i - 1];
    (*arr)[lo] = val;
    (*len)++;
}

/* binary search: returns 1 if val is present, 0 otherwise */
static int seq_contains(const seq_t *seq, size_t len, seq_t val)
{
    size_t lo = 0, hi = len;
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        if (seq[mid] < val)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo < len && seq[lo] == val;
}

/* Returns the n-th term of the sequence (a(1) is the first). */
seq_t a(idx_t n)
{
    static seq_t *seq = NULL;
    static size_t len  = 0;
    static size_t cap  = 0;
    static size_t next = 0;           /* next index to be processed */

    /* initialise on first call */
    if (seq == NULL) {
        cap = 16;
        seq = mem_new(seq_t, cap);
        seq[0] = (seq_t)1;            /* a(1) = 1 */
        len  = 1;
    }

    if (n == 0)
        return (seq_t)0;              /* undefined, but harmless */

    /* generate and insert elements until we have at least n terms */
    while (next < (size_t)(n - 1)) {
        seq_t x = seq[next];
        seq_insert(&seq, &len, &cap, (seq_t)3 * x / 2);  /* floor(3x/2) */
        seq_insert(&seq, &len, &cap, (seq_t)3 * x);      /* 3x       */
        ++next;
    }

    return seq[(size_t)(n - 1)];
}
